/// <summary>
/// JSON service for the agent test loop (harness: Tools/XppLoop/Invoke-XppLoop.ps1 in the Thien
/// repository). Exposed as /api/services/TEST_AutomationServices/TEST_AutomationService/<operation>.
/// Every operation returns a JSON text built with TEST_AutomationJson.
///
///   ping            service version, user, company, loaded Thien/SJP assemblies (to compare with
///                   the local build) and whether expected classes, methods, tables or fields exist
///   listSteps       the named seed and verify steps of TEST_AutomationStepRegistry
///   runStep         runs a step now and returns its summary and infolog
///   queueStep       runs a step as a batch job (TEST_AutomationStepTask) and returns the job id
///   runTests        runs SysTest classes or single tests as a batch job (TEST_AutomationTestTask)
///                   and returns the job id; the results are XPPTEST lines in its task log
///   startScenario   starts MD12 / MD31 through SJPBatchJobService.start, the ADF entry point,
///                   and returns the batch job it created
///   batchJobStatus  status, tasks and task logs of a batch job
///   stagingStatus   staging rows per status, archived rows, sample errors and run lock rows
///
/// The standard SysTestServices/SysTestService endpoint is disabled on the UDE, hence runTests.
/// For the UDE test environment only.
/// </summary>
public final class TEST_AutomationService
{
    // Raise when an operation or a reply changes, so the harness can tell an old deployment.
    public const str ServiceVersion = '4';

    // Must match the macros in SJPMDInventCountingService and SJPMDItemMasterImportService.
    #define.MD12LockScope('MD12.InventCounting')
    #define.MD31LockScope('MD31.ItemMaster')
    #define.MaxErrorsListed(10)
    #define.DefaultMaxLogLines(200)
}

